/** beginning to send a message */
export class BeginSendEntry extends MessageDescriptionEntry {
  sendDelay: BigDecimal = BigDecimal.ZERO; // send after this delay
  isUpdate: boolean = false; // whether this is a transmission update
  transmissionId: number = -1; // for pairing transmission updates with the original transmission

  parse(tokens: string[]): void {
    super.parse(tokens);
    this.sendDelay = this.getSimtimeToken(tokens, 'sd', false, this.sendDelay);
    this.isUpdate = this.getBoolToken(tokens, 'up', false, this.isUpdate);
    this.transmissionId = this.getInt64Token(tokens, 'tx', false, this.transmissionId);
  }

  print(): string {
    let out = '';
    out += 'BS';
    out += super.print();
    if (!this.sendDelay.equals(BigDecimal.ZERO)) out += ' sd ' + this.sendDelay.toString();
    if (this.isUpdate !== false) out += ' up ' + (this.isUpdate ? '1' : '0');
    if (this.transmissionId !== -1) out += ' tx ' + String(this.transmissionId);
    return out;
  }

  getAttributeNames(): string[] {
    const names: string[] = super.getAttributeNames();
    names.push('sd');
    names.push('up');
    names.push('tx');
    return names;
  }

  getAsString(attribute?: string): string | null {
    if (attribute === undefined) return 'BS';
    if (attribute === 'sd') return this.sendDelay.toString();
    if (attribute === 'up') return String(this.isUpdate);
    if (attribute === 'tx') return String(this.transmissionId);
    return super.getAsString(attribute);
  }

  getClassName(): string { return 'BeginSendEntry'; }

  static readonly code: string = 'BS';
  static readonly className: string = 'BeginSendEntry';
}

