/** Creates a fresh (unparsed) entry instance for the given entry code, or null if the code is not recognized. */
export function createEntry(code: string): EventLogTokenBasedEntry | null {
  switch (code) {
    case 'SB': return new SimulationBeginEntry();
    case 'SE': return new SimulationEndEntry();
    case 'E': return new EventEntry();
    case 'S': return new SnapshotEntry();
    case 'I': return new IndexEntry();
    case 'RF': return new ReferenceFoundEntry();
    case 'RA': return new ReferenceAddedEntry();
    case 'RR': return new ReferenceRemovedEntry();
    case 'CMB': return new ComponentMethodBeginEntry();
    case 'CME': return new ComponentMethodEndEntry();
    case 'MC': return new ModuleCreatedEntry();
    case 'MD': return new ModuleDeletedEntry();
    case 'GC': return new GateCreatedEntry();
    case 'GD': return new GateDeletedEntry();
    case 'CC': return new ConnectionCreatedEntry();
    case 'CD': return new ConnectionDeletedEntry();
    case 'MDC': return new ModuleDisplayStringChangedEntry();
    case 'GDC': return new GateDisplayStringChangedEntry();
    case 'CDC': return new ConnectionDisplayStringChangedEntry();
    case 'EDC': return new MessageDisplayStringChangedEntry();
    case 'CM': return new CreateMessageEntry();
    case 'CL': return new CloneMessageEntry();
    case 'DM': return new DeleteMessageEntry();
    case 'EN': return new EncapsulatePacketEntry();
    case 'DE': return new DecapsulatePacketEntry();
    case 'BS': return new BeginSendEntry();
    case 'ES': return new EndSendEntry();
    case 'SD': return new SendDirectEntry();
    case 'SH': return new SendHopEntry();
    case 'CE': return new CancelEventEntry();
    case 'MF': return new ModuleFoundEntry();
    case 'GF': return new GateFoundEntry();
    case 'CF': return new ConnectionFoundEntry();
    case 'EF': return new MessageFoundEntry();
    case 'MDF': return new ModuleDisplayStringFoundEntry();
    case 'GDF': return new GateDisplayStringFoundEntry();
    case 'CDF': return new ConnectionDisplayStringFoundEntry();
    case 'EDF': return new MessageDisplayStringFoundEntry();
    case 'BU': return new BubbleEntry();
    case 'CUC': return new CustomCreatedEntry();
    case 'CUD': return new CustomDeletedEntry();
    case 'CUM': return new CustomChangedEntry();
    case 'CUF': return new CustomFoundEntry();
    case 'CU': return new CustomEntry();
    default: return null;
  }
}

